import { LESSON_CELL_CHUNKS, LESSON_EPISODES, LESSON_QUESTS, LESSON_TITLE_CHUNKS, loadLessonCell, loadLessonTitles } from './__generated__/lessons-index';
import { createLessonStore, questsOverStore } from '../logic/lessons/lesson-store';

/**
 * The shipped upper-stage lesson cells (F-CURR-001 §3.10), generated by
 * scripts/build-lessons.mjs from content/episodes/stage-<n>/*.json. The manifest (episodes and
 * quest headers, English) loads at start; a cell's steps, scopes and glosses load on demand
 * from its content-hashed chunk, and the es / ko titles from the active locale's title chunk
 * (F-CURR-002 §10, row CM-5). `lessonContent` is the store the screens wait on.
 */
export const lessonContent = createLessonStore(
  { episodes: LESSON_EPISODES, cells: LESSON_CELL_CHUNKS, titles: LESSON_TITLE_CHUNKS },
  { cell: loadLessonCell, titles: loadLessonTitles },
);

export const lessonEpisodes = LESSON_EPISODES;

/** The lesson quests; a quest's `steps` read its cell's chunk, so they are empty until `lessonContent` has it. */
export const lessonQuests = questsOverStore(LESSON_QUESTS, lessonContent);
